    """Split Scheme source into tokens: parentheses and everything between spaces."""
    return source.replace('(', ' ( ').replace(')', ' ) ').split()


def parse_atom(token):
    """A number, a boolean, or a name (kept as a string)."""
    if token == '#t':
        return True
    if token == '#f':
        return False
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        return token


def parse(tokens):
    """Remove one expression from the front of `tokens` and return it."""
    if not tokens:
        raise SyntaxError('unexpected end of input')
    token = tokens.pop(0)
    if token == '(':
        exp = []
        while tokens and tokens[0] != ')':
            exp.append(parse(tokens))
        if not tokens:
            raise SyntaxError("missing ')'")
        tokens.pop(0)  # the ')'
        return exp
    if token == ')':
        raise SyntaxError("unexpected ')'")
    return parse_atom(token)


def read(source):
    """Text of exactly one expression -> its nested-list AST."""
    tokens = tokenize(source)
    exp = parse(tokens)
    if tokens:
        raise SyntaxError(f'unexpected {tokens[0]!r} after the expression')
    return exp

