def eval_expr(exp, env):
    if isinstance(exp, (bool, int, float)):          # self-evaluating
        return exp
    if isinstance(exp, str):                         # a name
        return env.lookup(exp)
    if not exp:
        raise SyntaxError('cannot evaluate ()')
    op = exp[0]
    if op in DERIVED:                                # rewrite, then evaluate the result
        return eval_expr(desugar(exp), env)
    if op == 'define':                               # (define name value)
        _, name, value = exp
        env.define(name, eval_expr(value, env))
        return name
    if op == 'lambda':                               # (lambda (params) body)
        _, params, body = exp
        return Procedure(params, body, env)
    if op == 'if':                                   # (if test then else)
        _, test, consequent, alternative = exp
        if eval_expr(test, env) is not False:        # in Scheme only #f is false
            return eval_expr(consequent, env)
        return eval_expr(alternative, env)
    procedure = eval_expr(op, env)                   # a call
    args = [eval_expr(arg, env) for arg in exp[1:]]
    return apply_proc(procedure, args)


def apply_proc(procedure, args):
    if isinstance(procedure, Procedure):
        if len(args) != len(procedure.params):
            raise TypeError(f'expected {len(procedure.params)} argument(s), got {len(args)}')
        frame = Frame(procedure.env)                 # parent: where it was DEFINED
        for name, value in zip(procedure.params, args):
            frame.define(name, value)
        return eval_expr(procedure.body, frame)
    if callable(procedure):                          # a primitive
        return procedure(*args)
    raise TypeError(f'{procedure!r} is not a procedure')


def evaluate(source, env):
    return eval_expr(read(source), env)


DERIVED = ('unless', 'let')


def desugar(exp):
    """Rewrite one derived expression into core forms. Syntax only: evaluates nothing."""
    op = exp[0]
    if op == 'unless':                    # (unless c a b) => (if c b a)
        _, test, usual, exceptional = exp
        return ['if', test, exceptional, usual]
    if op == 'let':                       # (let ((v e) ...) body) => ((lambda (v ...) body) e ...)
        _, bindings, body = exp
        names = [name for name, _ in bindings]
        values = [value for _, value in bindings]
        return [['lambda', names, body]] + values
    raise SyntaxError(f'not a derived expression: {op}')


env = make_global_env()
evaluate('(define square (lambda (x) (* x x)))', env)
print(evaluate('(let ((x 5)) (square (+ x 1)))', env))  # 36
